def alpha_mask(points, radmax):
 tri=Delaunay(points); mask=np.zeros((16,16),bool); polys=[]
 for simp in tri.simplices:
  p=points[simp]; a1=np.linalg.norm(p[0]-p[1]); b=np.linalg.norm(p[1]-p[2]); c=np.linalg.norm(p[2]-p[0]); area=abs(np.cross(p[1]-p[0],p[2]-p[0]))/2
  if area==0: continue
  rad=a1*b*c/(4*area)
  if rad<=radmax: polys.append(p.tolist())
 for r in range(16):
  for c in range(16):
   mask[r,c]=any(pip(r,c,p) for p in polys)
 return mask
